#include "cacheforge/persistence.hpp"
#include "cacheforge/distributed.hpp"
#include <cstring>
namespace cacheforge {
namespace { struct Header{uint32_t magic{0x43464731},key_len{},value_len{};int64_t expiry{};char type{};uint8_t pad[7]{};uint64_t checksum{};}; uint64_t checksum(const Header&h,const std::string&k,const std::string&v){std::string b(1,h.type);b.append(reinterpret_cast<const char*>(&h.expiry),sizeof(h.expiry));b+=k;b+=v;return ConsistentHashRing::hash(b);} }
Persistence::Persistence(std::filesystem::path d,bool e):dir_(std::move(d)),aof_(dir_/"cache.aof"),snapshot_(dir_/"cache.snapshot"),enabled_(e){if(enabled_)std::filesystem::create_directories(dir_);}
void Persistence::append(char t,const std::string&k,const std::string&v,int64_t x){if(!enabled_)return;std::lock_guard l(mutex_);Header h;h.key_len=(uint32_t)k.size();h.value_len=(uint32_t)v.size();h.expiry=x;h.type=t;h.checksum=checksum(h,k,v);std::ofstream f(aof_,std::ios::binary|std::ios::app);f.write((char*)&h,sizeof h);f.write(k.data(),k.size());f.write(v.data(),v.size());f.flush();}
void Persistence::log_set(const std::string&k,const std::string&v,std::optional<int64_t>x){append('S',k,v,x.value_or(-1));}void Persistence::log_del(const std::string&k){append('D',k,"",-1);}void Persistence::log_expire(const std::string&k,int64_t x){append('E',k,"",x);}void Persistence::log_flush(){append('F',"","",-1);}
bool Persistence::replay_file(const std::filesystem::path&p,Cache&c,bool snapshot,std::string&err){std::ifstream f(p,std::ios::binary);if(!f)return true;while(true){Header h;f.read((char*)&h,sizeof h);if(f.eof()&&f.gcount()==0)break;if(f.gcount()!=sizeof h){err="ignored incomplete trailing record in "+p.string();break;}if(h.magic!=0x43464731||h.key_len>16*1024*1024||h.value_len>256*1024*1024){err="stopped at corrupt record in "+p.string();break;}std::string k(h.key_len,'\0'),v(h.value_len,'\0');f.read(k.data(),k.size());f.read(v.data(),v.size());if(!f||checksum(h,k,v)!=h.checksum){err="ignored corrupt/incomplete trailing record in "+p.string();break;}try{if(h.type=='S')c.restore({k,v,h.expiry<0?std::optional<int64_t>{}:h.expiry});else if(!snapshot&&h.type=='D')c.erase(k);else if(!snapshot&&h.type=='E'){auto left=std::chrono::milliseconds(h.expiry)-std::chrono::duration_cast<std::chrono::milliseconds>(SystemClock::now().time_since_epoch());if(left.count()>0)c.expire(k,std::chrono::duration_cast<std::chrono::seconds>(left+std::chrono::milliseconds(999)));else c.erase(k);}else if(!snapshot&&h.type=='F')c.flush();else if(h.type!='S'){err="stopped at unknown record";break;}}catch(const std::exception&e){err=e.what();break;}}return true;}
bool Persistence::recover(Cache&c,std::string&err){if(!enabled_)return true;std::lock_guard l(mutex_);return replay_file(snapshot_,c,true,err)&&replay_file(aof_,c,false,err);}
bool Persistence::save_snapshot(Cache&c,std::string&err){if(!enabled_){err="persistence disabled";return false;}std::lock_guard l(mutex_);auto tmp=snapshot_;tmp+=".tmp";{std::ofstream f(tmp,std::ios::binary|std::ios::trunc);if(!f){err="cannot create snapshot temporary file";return false;}for(auto&r:c.records()){Header h;h.key_len=(uint32_t)r.key.size();h.value_len=(uint32_t)r.value.size();h.expiry=r.expires_unix_ms.value_or(-1);h.type='S';h.checksum=checksum(h,r.key,r.value);f.write((char*)&h,sizeof h);f.write(r.key.data(),r.key.size());f.write(r.value.data(),r.value.size());}f.flush();if(!f){err="snapshot write failed";return false;}}
 std::error_code ec;auto backup=snapshot_;backup+=".bak";std::filesystem::remove(backup,ec);if(std::filesystem::exists(snapshot_))std::filesystem::rename(snapshot_,backup,ec);if(ec){err=ec.message();return false;}std::filesystem::rename(tmp,snapshot_,ec);if(ec){if(std::filesystem::exists(backup))std::filesystem::rename(backup,snapshot_);err=ec.message();return false;}std::filesystem::remove(backup,ec);std::ofstream(aof_,std::ios::binary|std::ios::trunc);return true;}
}
